import{_ as n,c as a,o as i,a2 as t}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Datenschutzoptionen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy-choices.md","filePath":"de/guide/privacy-choices.md","lastUpdated":1793163976000}'),r={name:"de/guide/privacy-choices.md"};function s(l,e,o,h,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="datenschutzoptionen" tabindex="-1">Datenschutzoptionen <a class="header-anchor" href="#datenschutzoptionen" aria-label="Permalink to &quot;Datenschutzoptionen&quot;">​</a></h1><p>NueZip ist eine vollständig offline arbeitende Anwendung. Da all Ihre Daten auf Ihrem Gerät verbleiben, sammeln, verkaufen oder teilen wir keine persönlichen Informationen.</p><h2 id="daten-die-wir-lokal-vorhalten" tabindex="-1">Daten, die wir lokal vorhalten <a class="header-anchor" href="#daten-die-wir-lokal-vorhalten" aria-label="Permalink to &quot;Daten, die wir lokal vorhalten&quot;">​</a></h2><p>NueZip speichert alle Daten lokal auf Ihrem Mac:</p><ul><li>App-Einstellungen und -Konfiguration</li><li>Liste zuletzt geöffneter Dateien</li><li>Debug-Protokolle (falls aktiviert)</li><li>Im Schlüsselbund gespeicherte Passwörter (falls Sie sie zu speichern wählen)</li></ul><p>Keine dieser Daten wird auf einen Server hochgeladen.</p><h2 id="ihre-rechte" tabindex="-1">Ihre Rechte <a class="header-anchor" href="#ihre-rechte" aria-label="Permalink to &quot;Ihre Rechte&quot;">​</a></h2><p>Da NueZip keine persönlichen Daten auf unseren Servern sammelt oder speichert, gibt es keine persönlichen Daten, auf die wir zugreifen, die wir löschen oder übertragen könnten. Alle Ihre Daten können direkt in der App verwaltet oder durch Entfernen des Container-Ordners der App gelöscht werden:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><h2 id="kein-verkauf" tabindex="-1">Kein Verkauf <a class="header-anchor" href="#kein-verkauf" aria-label="Permalink to &quot;Kein Verkauf&quot;">​</a></h2><p>NueZip verkauft keine persönlichen Informationen. Wir verwenden keine Analysen, Werbung oder Tracking-Dienste von Drittanbietern irgendeiner Art.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Wenn Sie Fragen zu Datenschutzoptionen haben, öffnen Sie ein Issue unter: <code>https://github.com/nuezip/nuezip/issues</code></p>',13)])])}const k=n(r,[["render",s]]);export{u as __pageData,k as default};
